export class WriteThroughCache<T> {
  constructor(private cache: CacheStore, private db: DatabaseStore) {}

  async get(key: string): Promise<T | null> {
    const cached = await this.cache.get(key);
    if (cached) return JSON.parse(cached);

    // Transparently fetch from DB on miss
    const record = await this.db.fetchById(key);
    if (record) {
      await this.cache.set(key, JSON.stringify(record), 3600);
    }
    return record;
  }

  async set(key: string, value: T): Promise<void> {
    // Synchronously write to DB first to ensure durability
    await this.db.persist(key, value);
    // Update in-memory cache before acknowledging client
    await this.cache.set(key, JSON.stringify(value), 3600);
  }
}
